-- P0-1 MANUAL PREFLIGHT (READ ONLY). Run in phpMyAdmin before apply.
SELECT VERSION() server_version,DATABASE() database_name;
SELECT table_name,column_name,column_type,is_nullable,column_key FROM information_schema.columns WHERE table_schema=DATABASE() AND ((table_name='users' AND column_name IN ('user_id','student_id','employee_id')) OR (table_name IN ('colleges','departments','academic_programs','course_offerings') AND column_name IN ('college_id','department_id','academic_program_id','course_offering_id'))) ORDER BY table_name,ordinal_position;
SELECT u.organizational_unit_id,u.unit_code,u.unit_name,t.type_code,p.unit_code parent_code,u.is_active FROM organizational_units u JOIN organizational_unit_types t ON t.unit_type_id=u.unit_type_id LEFT JOIN organizational_units p ON p.organizational_unit_id=u.parent_unit_id WHERE u.unit_code IN ('PRES','VP_ADMIN','7','71','72','73','731','732','733','734','735','736','REG_OFFICE','EXAM_OFFICE') ORDER BY u.unit_code;
SELECT e.employee_id,e.employee_number,u.unit_code FROM employees e JOIN organizational_units u ON u.organizational_unit_id=e.organizational_unit_id WHERE u.unit_code IN ('VP_ADMIN','7','REG_OFFICE','EXAM_OFFICE','732','735') ORDER BY u.unit_code,e.employee_id;
SELECT table_name,column_name,constraint_name FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND referenced_table_name='organizational_units' AND referenced_column_name='organizational_unit_id' ORDER BY table_name,column_name;
SELECT 'boards' source,COUNT(*) refs FROM boards x JOIN organizational_units u ON u.organizational_unit_id=x.organizational_unit_id WHERE u.unit_code IN ('VP_ADMIN','REG_OFFICE','EXAM_OFFICE') UNION ALL SELECT 'colleges',COUNT(*) FROM colleges x JOIN organizational_units u ON u.organizational_unit_id=x.organizational_unit_id WHERE u.unit_code IN ('VP_ADMIN','REG_OFFICE','EXAM_OFFICE') UNION ALL SELECT 'departments',COUNT(*) FROM departments x JOIN organizational_units u ON u.organizational_unit_id=x.organizational_unit_id WHERE u.unit_code IN ('VP_ADMIN','REG_OFFICE','EXAM_OFFICE') UNION ALL SELECT 'employees',COUNT(*) FROM employees x JOIN organizational_units u ON u.organizational_unit_id=x.organizational_unit_id WHERE u.unit_code IN ('VP_ADMIN','REG_OFFICE','EXAM_OFFICE') UNION ALL SELECT 'employee_positions',COUNT(*) FROM employee_positions x JOIN organizational_units u ON u.organizational_unit_id=x.organizational_unit_id WHERE u.unit_code IN ('VP_ADMIN','REG_OFFICE','EXAM_OFFICE') UNION ALL SELECT 'employee_unit_assignments',COUNT(*) FROM employee_unit_assignments x JOIN organizational_units u ON u.organizational_unit_id=x.organizational_unit_id WHERE u.unit_code IN ('VP_ADMIN','REG_OFFICE','EXAM_OFFICE') UNION ALL SELECT 'child_units',COUNT(*) FROM organizational_units x JOIN organizational_units u ON u.organizational_unit_id=x.parent_unit_id WHERE u.unit_code IN ('VP_ADMIN','REG_OFFICE','EXAM_OFFICE');
SELECT student_id,GROUP_CONCAT(user_id ORDER BY user_id) user_ids FROM users WHERE student_id IS NOT NULL GROUP BY student_id HAVING COUNT(*)>1;
SELECT employee_id,GROUP_CONCAT(user_id ORDER BY user_id) user_ids FROM users WHERE employee_id IS NOT NULL GROUP BY employee_id HAVING COUNT(*)>1;
SELECT r.role_code,p.permission_code FROM role_permissions rp JOIN roles r ON r.role_id=rp.role_id JOIN permissions p ON p.permission_id=rp.permission_id WHERE r.role_code IN ('exam_officer','registration_officer','doctor_instructor','student') ORDER BY r.role_code,p.permission_code;
SELECT 'linked' status,user_id,email,student_id,employee_id FROM users WHERE student_id IS NOT NULL OR employee_id IS NOT NULL;
SELECT 'unlinked' status,user_id,email,student_id,employee_id FROM users WHERE student_id IS NULL AND employee_id IS NULL;
SELECT u.user_id,u.email,COUNT(DISTINCT s.student_id) student_candidates,COUNT(DISTINCT e.employee_id) employee_candidates FROM users u LEFT JOIN students s ON BINARY s.email=BINARY u.email LEFT JOIN employees e ON BINARY e.email=BINARY u.email GROUP BY u.user_id,u.email HAVING student_candidates>1 OR employee_candidates>1;
SELECT ou.organizational_unit_id university_scope_reference_id,ou.unit_code,ou.unit_name FROM organizational_units ou WHERE ou.unit_code='PRES';
SET @p01_scope_report=IF(EXISTS(SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='user_access_scopes'),'SELECT s.*,''invalid_or_orphan'' finding FROM user_access_scopes s LEFT JOIN organizational_units root ON s.scope_type=''university'' AND root.organizational_unit_id=s.scope_id AND root.unit_code=''PRES'' LEFT JOIN colleges c ON s.scope_type=''college'' AND c.college_id=s.scope_id LEFT JOIN departments d ON s.scope_type=''department'' AND d.department_id=s.scope_id LEFT JOIN academic_programs p ON s.scope_type=''program'' AND p.academic_program_id=s.scope_id LEFT JOIN course_offerings co ON s.scope_type=''section'' AND co.course_offering_id=s.scope_id WHERE CASE s.scope_type WHEN ''university'' THEN root.organizational_unit_id WHEN ''college'' THEN c.college_id WHEN ''department'' THEN d.department_id WHEN ''program'' THEN p.academic_program_id WHEN ''section'' THEN co.course_offering_id ELSE NULL END IS NULL;','SELECT ''user_access_scopes_not_created'' finding');
PREPARE p01_stmt FROM @p01_scope_report; EXECUTE p01_stmt; DEALLOCATE PREPARE p01_stmt;
SET @p01_operator_report=IF(EXISTS(SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='user_access_scopes'),'SELECT u.user_id,u.email,r.role_code FROM users u JOIN user_roles ur ON ur.user_id=u.user_id AND ur.is_active=1 JOIN roles r ON r.role_id=ur.role_id AND r.role_code IN (''exam_officer'',''registration_officer'') LEFT JOIN user_access_scopes s ON s.user_id=u.user_id AND s.is_active=1 LEFT JOIN organizational_units root ON s.scope_type=''university'' AND root.organizational_unit_id=s.scope_id AND root.unit_code=''PRES'' LEFT JOIN colleges c ON s.scope_type=''college'' AND c.college_id=s.scope_id LEFT JOIN departments d ON s.scope_type=''department'' AND d.department_id=s.scope_id LEFT JOIN academic_programs p ON s.scope_type=''program'' AND p.academic_program_id=s.scope_id LEFT JOIN course_offerings co ON s.scope_type=''section'' AND co.course_offering_id=s.scope_id GROUP BY u.user_id,u.email,r.role_code HAVING COUNT(root.organizational_unit_id)+COUNT(c.college_id)+COUNT(d.department_id)+COUNT(p.academic_program_id)+COUNT(co.course_offering_id)=0;','SELECT ''user_access_scopes_not_created; all operational users need reviewed scopes'' finding');
PREPARE p01_stmt FROM @p01_operator_report; EXECUTE p01_stmt; DEALLOCATE PREPARE p01_stmt;
SELECT IF((SELECT COUNT(*) FROM organizational_units WHERE unit_code='PRES')=1 AND NOT ((SELECT COUNT(*) FROM organizational_units WHERE unit_code='7')=1 AND (SELECT COUNT(*) FROM organizational_units WHERE unit_code='VP_ADMIN')=1) AND NOT EXISTS(SELECT student_id FROM users WHERE student_id IS NOT NULL GROUP BY student_id HAVING COUNT(*)>1) AND NOT EXISTS(SELECT employee_id FROM users WHERE employee_id IS NOT NULL GROUP BY employee_id HAVING COUNT(*)>1) AND EXISTS(SELECT 1 FROM organizational_unit_types WHERE type_code='vice_presidency') AND EXISTS(SELECT 1 FROM organizational_unit_types WHERE type_code='directorate') AND EXISTS(SELECT 1 FROM organizational_unit_types WHERE type_code='office'),1,0) can_apply;
